"""Publish native-measured handoffs and complete authored RILL tools."""
from pathlib import Path
import json,re
from compiler_publication import publish
ROOT=Path(__file__).resolve().parents[1];W=ROOT/'workbench/toolchain';Q=ROOT/'qa/toolchain';C=ROOT/'site/content/bootstrap'
def front(t,n,d,src):return '+++\n'+f'title = {json.dumps(t)}\nweight = {n}\ndescription = {json.dumps(d)}\ndownload = "{src}"\ndownload_group = "toolchain"\n'+'+++\n\n'
def fence(k,t):return '```'+k+'\n'+t.replace('\r\n','\n').rstrip('\n')+'\n```\n\n'
facts=json.loads((Q/'self-build-facts.json').read_text());seed=len((W/'RILLBOOT.COM').read_bytes());wide=len((ROOT/'workbench/ir86/IRWIDE.COM').read_bytes());native_assembler=len((ROOT/'workbench/asm86a/ASM86A.COM').read_bytes())
(Q/'build-facts.json').write_text(json.dumps({'native_ir_bytes':wide,'ir_compiler_seed_bytes':seed,'tools':facts},indent=2)+'\n')
capacity=json.loads((Q/'local-capacity.json').read_text())
t=front('The compiler self-build',133,'Establish the compiler frame convention and compare two matching generations.','RILL.RIL')
t+=f'RC43.RIL is the completed RILL compiler, saved as RILL.RIL. Its record, local-declaration and procedure routines already support sixty-four local slots and sixteen parameters. The IR-written seed built RC43.COM; preserve it as RBOOT.COM. VIEW.BAS must report **{capacity["boot_binary_bytes"]} bytes**.\n\n'
t+='## Let RILL establish its own frames\n\nRILLBOOT reserves sixteen local slots in the programs it compiles. RILL reserves sixty-four. RBOOT therefore uses sixteen-slot frames in its own implementation but emits sixty-four-slot frames. Compile the unchanged compiler source once with RBOOT to establish R0 using the RILL frame convention:\n\n'+fence('dos','COPY RILL.RIL SOURCE.RIL\nCHECK RBOOT\nCOPY RESULT.IR SOURCE.IR\nCHECK IWKEEP\nCOPY RESULT.ASM SOURCE.ASM\nCHECK ASMAKEEP\nCOPY RESULT.COM R0.COM')
t+=f'Require compiler `OK RESULT.IR {capacity["ir_bytes"]:010}`, translator `OK RESULT.ASM {capacity["assembly_bytes"]:010} text bytes`, assembler `OK RESULT.COM {facts["RILL"]:05} bytes`, and each PASS before the following copy. VIEW.BAS must show R0.COM length {facts["RILL"]}. RBOOT and R0 need not have identical bytes: their builders reserve different frames. All comparisons below start with R0.\n\n'
t+='## Build the first matching self-copy\n\n'+fence('dos','COPY RILL.RIL SOURCE.RIL\nCHECK R0\nCOPY RESULT.IR SOURCE.IR\nCHECK IWKEEP\nCOPY RESULT.ASM SOURCE.ASM\nCHECK ASMAKEEP\nCOPY RESULT.COM R1.COM')
t+='Each copy follows its own fresh OK and PASS. Use VIEW.BAS to check both lengths before comparing:\n\n'+fence('dos','ECHO N>NO.TXT\nCOMP R0.COM R1.COM <NO.TXT')
t+='Require no differences. NO.TXT answers N if COMP asks whether to compare more files. A successful comparison is separate from the preceding tools\' success reports.\n\n## Let that copy do the same job\n\n'+fence('dos','COPY RILL.RIL SOURCE.RIL\nCHECK R1\nCOPY RESULT.IR SOURCE.IR\nCHECK IWKEEP\nCOPY RESULT.ASM SOURCE.ASM\nCHECK ASMAKEEP\nCOPY RESULT.COM R2.COM\nCOMP R0.COM R2.COM <NO.TXT')
t+=f'Require each OK and PASS and no COMP differences. R0, R1, and R2 must all have length {facts["RILL"]}. This is the same RILL source compiled through the published IR translator and assembler. Preserve these matching copies for the toolchain collection.\n\n'
t+='## A rejected input must stay rejected\n\nCreate BAD.RIL:\n\n'+fence('rill','fn main(){return missing(1);}')+fence('dos','COPY BAD.RIL SOURCE.RIL\nCHECK R2')+'With a final CR/LF after the source line, require `ERROR 0000000002 CODE 00004` and FAIL. The accepted RESULT.IR must remain unchanged. An unexpected PASS fails the check. Restore RILL.RIL as SOURCE.RIL before another self-build.\n\nKeep the compiler seed, native IR bridge, original native assembler and their sources on a separate labeled disk.\n'
publish('rc','133-the-compiler-self-build.md',t,45)
# Complete source notebooks group the ports by the same routines used in their native constructions.
for name,collection,weight,file,description in [('IR86','toolchain',1,'01-ir86-in-rill.md','The same virtual-machine operations, with a RILL parser and a separate native binding.'),('ASM86A','toolchain',2,'02-asm86-in-rill.md','The streaming assembler, symbol pages, and 8086 encodings implemented in RILL.')]:
 t=front(name+' in RILL',weight,description,name+'.RIL')+description+'\n\n'
 t+=f'The complete {name}.RIL below uses the ordinary RILL language and portable services. Begin after the completed RILL compiler and its self-build comparisons. Build it with the preserved R0 compiler, then IWKEEP and ASMAKEEP. Require a fresh OK and PASS at each boundary before copying the next result. Preserve the resulting executable as '+('I0.COM' if name=='IR86' else 'A0.COM')+f'; VIEW.BAS must show **{facts[name]} bytes**.\n\n'
 if name=='IR86':
  t+='The scanner and statement decoder implement the IR contract. The operation records contain argument classes, stack effects, and authored assembly templates. The header and runtime procedures are the 8086/DOS binding. They are not physical-register operations in the language. The input line and ordinary token stay bounded; RESULT.ASM streams through its owned temporary file.\n\n'
 else:t+='The parser, two passes, exact-spelling hash chains, symbol-page selection, fixed-width operands, and emitters have the same jobs as in the native ASM86A construction. Each symbol record is initialized explicitly. Its page is an opaque block handle and its record location a byte offset. No processor segment is exposed to the RILL implementation.\n\nThe encodings retain the native assembler\'s fixed choices: explicit word displacements, full-width immediate arithmetic, and an opposite short branch plus near JMP for Jcc NEAR. No later-CPU instruction is needed. The 8192-symbol and 61184-byte image bounds remain real.\n\n'
 t+='## Complete source, by routine\n\nStart a plain text '+name+'.RIL. Enter the declarations, then append each complete procedure in the displayed order. These are parts of one complete tool; a copied fragment is not a standalone program. The compiler self-build exercise supplies R0. Preserve the native IWKEEP and ASMAKEEP as its translator and assembler.\n\n'
 text=(W/(name+'.RIL')).read_text();parts=re.split(r'(?m)(?=^fn )',text);t+='### Declarations\n\n'+fence('rill',parts[0])
 for block in parts[1:]:
  fn=re.match(r'fn (\w+)\(([^)]*)\)',block)
  t+='### '+fn[1]+'\n\n'+fence('rill',block)
 t+='## Complete build\n\n'+fence('dos',f'COPY {name}.RIL SOURCE.RIL\nCHECK R0\nCOPY RESULT.IR SOURCE.IR\nCHECK IWKEEP\nCOPY RESULT.ASM SOURCE.ASM\nCHECK ASMAKEEP\nCOPY RESULT.COM '+('I0.COM' if name=='IR86' else 'A0.COM'))
 t+='Require each OK and PASS **before** the next copy. The complete source link is the same file assembled from the routine blocks above.\n\n'
 if name=='IR86':
  t+='Test the fixed-file translator with this complete IR program:\n\n'+fence('ir','PROC MAIN 0 0\nLIT 65\nPUTC\nLIT 0\nRETURN')+'Save it as TEST.IR. COPY TEST.IR SOURCE.IR and run CHECK I0. Require OK and PASS, copy RESULT.ASM to SOURCE.ASM, and run CHECK ASMAKEEP. Save the accepted RESULT.COM as TRY.COM; CHECK TRY displays A and reports PASS.\n\nFor rejection, replace its LIT 65 with LIT 65536. CHECK I0 must report `IR ERROR 0000000002 CODE 00002` and FAIL, preserving the accepted RESULT.ASM. An unexpected PASS fails this check.\n'
 else:t+='Test A0 with SOURCE.ASM containing `MOV DL,65`, `MOV AH,2`, `INT 21H`, `MOV AX,4C00H`, and `INT 21H`, each on its own line. Require `OK RESULT.COM 00011 bytes` and PASS. VIEW.BAS must show `B2 41 B4 02 CD 21 B8 00 4C CD 21`; save it as TRY.COM. CHECK TRY displays A and reports PASS.\n\nFor rejection, use SOURCE.ASM containing `MOV CS,AX`. CHECK A0 must report `ERROR 0000000001 CODE 00001` and FAIL, preserving RESULT.COM. An unexpected PASS fails the check.\n'
 routes=['/bootstrap/ir86/061-ir86-in-rill/'] if name=='IR86' else ['/bootstrap/rc/134-asm86a-in-rill/','/bootstrap/rill/134-asm86a-in-rill/']
 publish(collection,file,t,aliases=routes)
t=front('Building the Three Tools',3,'Build the compiler, translator, and assembler, then let all three rebuild all three.','TOOLCHN.ZIP')
t+='The complete ladder is:\n\n'+fence('text','GW-BASIC\n  BOOTASM\n    ASM86\n      ASMA0\n        ASM86A\n          native streaming IR86\n            RILL0\n              IR-written RILLBOOT compiler seed\n                RILL-written compiler, IR86, and ASM86A\n                  two matching rebuild generations')
t+=f'ASMA0 is the streaming-seed collection between ASM86 and ASM86A. The [RB collection](../../rb/index.html) constructs RILLBOOT, the IR-written compiler seed. The [RC collection](../../rc/index.html) constructs the compiler in RILL, including its storage and procedure frames, and proves matching self-builds. The final three source programs are RILL.RIL, IR86.RIL, and ASM86A.RIL. They share the published language, not a special tool-building escape.\n\n## Reproduce the disk workbench\n\nBegin with the tested native {native_assembler}-byte ASM86A preserved as ASMAKEEP.COM. Keep its BASIC/native ladder sources. Copy the source collection to a hard-disk work directory and run:\n\n'+fence('dos','TMAKE')
t+=f'TMAKE first builds IRWIDE.COM ({wide} bytes) with ASMAKEEP. That native translator and assembler rebuild RILL0, then compile and run its HI program. They next build RILLBOOT.COM ({seed} bytes) from the authored RILLBOOT.IR. The compiler seed builds the completed RC43 source, RILL.RIL, as RBOOT.COM. RBOOT compiles that unchanged source with sixty-four-slot frames to establish R0.COM. R0 then compiles IR86.RIL and ASM86A.RIL, using the native translator and assembler to establish I0 and A0. TMAKE checks every tool status immediately and stops at the first nonzero status. Its visible PASS markers identify the RILL0 program and each completed initial or rebuild pipeline for the three full tools.\n\n'
t+='The A/I/R letters below mean assembler, IR translator, and RILL compiler:\n\n| Tool | First RILL build | First rebuild | Second rebuild | Bytes |\n|---|---|---|---|---|\n'+''.join(f'| {name} | {letter}0.COM | {letter}1.COM | {letter}2.COM | {facts[name]} |\n' for name,letter in [('ASM86A','A'),('IR86','I'),('RILL','R')])+'\n'
t+='Each rebuild generation uses the preceding RILL-written compiler, translator, and assembler for **all three source programs**. The preserved native tools are not silently used in that closed loop. TMAKE.BAT is ordinary DOS batch text; it supplies no executable bytes. Its complete source is:\n\n'+fence('dos',(W/'TMAKE.BAT').read_text())
publish('toolchain','03-building-the-toolchain.md',t,aliases=['/bootstrap/rc/135-the-complete-toolchain/','/bootstrap/rill/135-the-complete-toolchain/'])
t=front('Comparing Two Rebuild Generations',4,'Compare all three tools and use generation two to compile a complete program.','TOOLCHN.ZIP')
t+='Begin after TMAKE has completed successfully. Keep A0/A1/A2, I0/I1/I2, and R0/R1/R2. Each group must have the same length and identical bytes. These are independent checks of builds that already returned success.\n\n'
t+='| Tool | Bytes in every generation |\n|---|---|\n'+''.join(f'| {name} | {facts[name]} |\n' for name in ['ASM86A','IR86','RILL'])+'\n'
t+='## Compare the generations\n\n'+fence('dos','ECHO N>NO.TXT\nCOMP A0.COM A1.COM <NO.TXT\nCOMP A0.COM A2.COM <NO.TXT\nCOMP I0.COM I1.COM <NO.TXT\nCOMP I0.COM I2.COM <NO.TXT\nCOMP R0.COM R1.COM <NO.TXT\nCOMP R0.COM R2.COM <NO.TXT')+'Every comparison must report no differences, and VIEW.BAS must show the corresponding length in the table. NO.TXT answers N if COMP asks whether to compare more files. Build status and byte comparison are independent observations.\n\n'
t+='## Use generation two\n\nCreate HI.RIL:\n\n'+fence('rill','fn main(){putc(72);putc(73);return 0;}')+fence('dos','COPY HI.RIL SOURCE.RIL\nCHECK R2\nCOPY RESULT.IR SOURCE.IR\nCHECK I2\nCOPY RESULT.ASM SOURCE.ASM\nCHECK A2\nCOPY RESULT.COM HI.COM\nCHECK HI')+'Require OK and PASS before each copy. HI displays HI and reports PASS.\n\nFor a rejection, give R2 SOURCE.RIL containing `fn main(){return missing();}`. With a final CR/LF after the source line, require `ERROR 0000000002 CODE 00004` and FAIL. RESULT.IR must remain unchanged. An unexpected PASS fails the check. Restore the accepted source before another run.\n\n'
t+='Keep the source, preserved native builders, and matching generations separately labeled. A toolchain is established by reproducible successful translations and executable behavior, not by retaining an unexplained binary.\n'
publish('toolchain','04-comparing-generations.md',t,aliases=[])
print('Rendered complete source notebooks, compiler self-build, and closed toolchain loop')
